const state = { role: null, page: 'login', cart: [], modal: null, selectedTask: null, query: '', toast: null };
const clone = (value) => JSON.parse(JSON.stringify(value));
const db = clone(seed);
const money = (number) => `S/ ${Number(number || 0).toFixed(2)}`;
const cap = (value) => String(value).charAt(0).toUpperCase() + String(value).slice(1);
const roleMeta = { administrador: { name: 'Frank Admin', label: 'ADMINISTRADOR', initial: 'F' }, almacenero: { name: 'Carlos Ramos', label: 'ALMACENERO', initial: 'C' }, vendedor: { name: 'Ana Torres', label: 'VENDEDOR', initial: 'A' } };
const icon = (name) => `<i class="bi bi-${name}"></i>`;
const badge = (text, kind = '') => `<span class="badge ${kind}">${text}</span>`;
const empty = (iconName, title, text) => `<div class="empty">${icon(iconName)}<strong>${title}</strong><p>${text}</p></div>`;

function clock() {
  return new Intl.DateTimeFormat('es-PE', { timeZone: 'America/Lima', day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());
}

function navItems(role) {
  const admin = [
    ['GENERAL', 'dashboard', 'speedometer2', 'Dashboard gerencial'], ['NEGOCIO', 'sales', 'receipt', 'Ventas'], ['', 'purchases', 'truck', 'Órdenes de compra'], ['', 'reports', 'bar-chart-line', 'Reportes'],
    ['WMS', 'locations', 'geo-alt', 'Zonas y ubicaciones'], ['', 'tasks', 'arrows-move', 'Tareas dirigidas'], ['INVENTARIO', 'inventory', 'boxes', 'Inventario por ubicación'], ['', 'products', 'box-seam', 'Productos y SKU'], ['', 'lots', 'layers', 'Lotes y vencimientos'], ['', 'kardex', 'arrow-left-right', 'Kardex'], ['', 'health', 'heart-pulse', 'Salud de stock'], ['', 'audits', 'clipboard-check', 'Auditorías'], ['ADMINISTRACIÓN', 'users', 'people', 'Usuarios'], ['', 'suppliers', 'buildings', 'Proveedores'], ['', 'catalogs', 'tags', 'Catálogos maestros'], ['', 'settings', 'gear', 'Configuración'],
  ];
  const warehouse = [
    ['OPERACIÓN', 'warehouse', 'grid-1x2', 'Panel operativo'], ['', 'purchases', 'truck', 'Mercadería por recibir'], ['WMS CORE', 'locations', 'geo-alt', 'Zonas, LOC y stock'], ['', 'tasks', 'arrows-move', 'Tareas y traslados'], ['CONTROL', 'inventory', 'boxes', 'Inventario por ubicación'], ['', 'products', 'box-seam', 'Productos y stock'], ['', 'lots', 'layers', 'Lotes y vencimientos'], ['', 'kardex', 'arrow-left-right', 'Kardex'], ['', 'audits', 'clipboard-check', 'Conteo físico'], ['', 'health', 'heart-pulse', 'Salud de stock'],
  ];
  const seller = [['VENTA', 'pos', 'cart3', 'Punto de venta'], ['', 'sales', 'receipt', 'Mis ventas'], ['', 'products', 'search', 'Consultar precio y stock']];
  return role === 'administrador' ? admin : role === 'almacenero' ? warehouse : seller;
}

function sidebar() {
  const meta = roleMeta[state.role];
  const links = navItems(state.role).map(([section, key, ico, label]) => `${section ? `<div class="nav-section">${section}</div>` : ''}<button class="nav-link ${state.page === key ? 'active' : ''}" data-nav="${key}">${icon(ico)} ${label}${key === 'tasks' ? badge(db.tasks.filter((t) => t.status !== 'Completada').length, 'warn') : ''}</button>`).join('');
  return `<aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">${icon('shop')}</span><span><strong>DON PEPE</strong><small>${state.role === 'almacenero' ? 'CENTRO DE INVENTARIO' : state.role === 'vendedor' ? 'PUNTO DE VENTA' : 'GESTIÓN INTEGRAL'}</small></span></div>${state.role === 'almacenero' ? `<button class="warehouse-cta" data-nav="purchases">${icon('truck')} Mercadería por recibir</button>` : ''}<nav>${links}</nav><div class="sidebar-user"><span class="avatar">${meta.initial}</span><div><strong>${meta.name}</strong><small>${meta.label}</small></div></div></aside>`;
}

function topbar() {
  const meta = roleMeta[state.role];
  return `<header class="topbar"><div class="topbar-left"><button class="btn btn-outline btn-sm" data-action="toggle-sidebar">${icon('list')}</button><span class="status"><b>●</b>Sistema activo</span><span class="clock" data-clock>${clock()} · PET</span></div><div class="topbar-right"><button class="btn btn-outline btn-sm" data-action="toast">${icon('bell')} 7</button><span class="profile"><span class="avatar">${meta.initial}</span>${meta.name}</span><button class="btn btn-outline btn-sm" data-action="logout" title="Cerrar sesión">${icon('box-arrow-right')}</button></div></header>`;
}

function pageHead(eyebrow, title, description, actions = '') { return `<section class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></section>`; }
function metric(value, label, iconName, accent) { return `<article class="metric" style="--accent:${accent}">${icon(iconName)}<strong class="metric-value">${value}</strong><span class="metric-label">${label}</span></article>`; }

function dashboard() {
  const tasks = db.tasks.filter((t) => t.status !== 'Completada');
  return `${pageHead('VISIÓN GENERAL', 'DASHBOARD GERENCIAL', 'Control central de inventario, operación WMS y ventas de Don Pepe.', `<button class="btn btn-primary" data-nav="products">${icon('plus-lg')} Nuevo producto</button><button class="btn btn-outline" data-nav="tasks">${icon('arrows-move')} Crear tarea</button>`)}
  <div class="metrics">${metric(db.products.length, 'SKU activos', 'box-seam', 'var(--blue)')}${metric(db.products.reduce((a,p)=>a+p.stock,0), 'Unidades en stock', 'boxes', 'var(--green)')}${metric(money(db.products.reduce((a,p)=>a+p.stock*p.price,0)), 'Valor de inventario', 'cash-stack', 'var(--yellow)')}${metric(tasks.length, 'Acciones operativas', 'exclamation-triangle', 'var(--red)')}</div>
  <div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>MOVIMIENTOS SEMANALES</h2><small>Entradas y salidas · esta semana</small></div>${badge('ENTRADAS / SALIDAS','purple')}</div><div class="bars">${[55,82,35,96,63,76,45].map((v,i)=>`<div class="bar-col"><small>${v}</small><div class="bar" style="height:${v}%"></div><small>${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'][i]}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>STOCK POR CATEGORÍA</h2><small>Distribución actual</small></div><button class="btn btn-outline btn-sm" data-nav="reports">Ver reporte</button></div>${['Bebidas','Abarrotes','Lácteos','Snacks','Congelados'].map((x,i)=>`<div class="list-row"><span class="row-icon">${icon(['cup-straw','basket','cup-hot','cookie','snow'][i])}</span><div class="grow"><strong>${x}</strong><small>${[86,67,51,39,27][i]} unidades</small></div><strong>${[32,25,19,14,10][i]}%</strong></div>`).join('')}</section></div>
  <div class="grid-even" style="margin-top:16px"><section class="panel"><div class="panel-head"><div><h2>STOCK CRÍTICO</h2><small>Requiere reabastecimiento o compra</small></div><button class="btn btn-outline btn-sm" data-nav="health">Ver salud</button></div>${criticalList()}</section><section class="panel"><div class="panel-head"><div><h2>ÚLTIMA ACTIVIDAD</h2><small>Movimientos confirmados</small></div><button class="btn btn-outline btn-sm" data-nav="kardex">Ir al kardex</button></div>${activityList()}</section></div>`;
}

function criticalList() { return db.products.filter(p => p.stock <= p.min).map((p) => `<div class="list-row"><span class="row-icon" style="color:var(--red)">${icon('exclamation-triangle')}</span><div class="grow"><strong>${p.name}</strong><small>${p.loc} · mínimo ${p.min}</small><div class="progress"><b style="width:${Math.min(100,p.stock/p.min*100)}%;background:var(--red)"></b></div></div><strong style="color:var(--red)">${p.stock}/${p.min}</strong></div>`).join('') || empty('check-circle','Inventario saludable','No hay SKU por debajo de su mínimo.'); }
function activityList() { return [['arrow-down','Recepción confirmada','48 und. Inca Kola · REC-01','var(--green)'],['arrow-left-right','Reabastecimiento iniciado','Pilsen Callao · RSV-SECO-01 → PCK-SECO-01','var(--yellow)'],['cart-check','Venta V-00192','S/ 29.60 · Ana Torres','var(--blue)'],['clipboard-check','Conteo con diferencia','Lay’s Clásicas · pendiente de aprobar','var(--red)']].map(x=>`<div class="list-row"><span class="row-icon" style="color:${x[3]}">${icon(x[0])}</span><div class="grow"><strong>${x[1]}</strong><small>${x[2]}</small></div><small>hoy</small></div>`).join(''); }

function warehouse() { return `${pageHead('OPERACIÓN WMS', 'PANEL OPERATIVO', 'Prioriza lo que debe recibirse, moverse, contarse o reabastecerse.', `<button class="btn btn-primary" data-nav="tasks">${icon('arrows-move')} Ver tareas</button>`)}<div class="metrics">${metric(db.orders.filter(o=>o.status!=='Recibida').length,'Recepciones pendientes','truck','var(--orange)')}${metric(db.tasks.filter(t=>t.status==='Pendiente').length,'Tareas por tomar','inboxes','var(--yellow)')}${metric(db.tasks.filter(t=>t.status==='En proceso').length,'En ejecución','arrow-repeat','var(--blue)')}${metric(db.audits.filter(a=>a.status==='Pendiente').length,'Diferencias por revisar','clipboard-x','var(--red)')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>PRÓXIMA ACCIÓN SUGERIDA</h2><small>Decisión guiada por urgencia y disponibilidad</small></div></div><div class="task" style="--accent:var(--orange)"><div class="task-top">${badge('RECEPCIÓN','warn')}${badge('ALTA','danger')}</div><h3>Recibir OC-2026-0048</h3><p>Arca Continental Lindley llegó a recepción. Verifica cantidades y genera tareas de ubicación dirigida.</p><div class="route"><span>MUELLE</span>${icon('arrow-right')}<span>REC-01</span></div><button class="btn btn-primary" data-nav="receive">${icon('clipboard-check')} Iniciar recepción</button></div></section><section class="panel"><div class="panel-head"><div><h2>COLAS DE TRABAJO</h2><small>Estado actual del almacén</small></div></div>${db.tasks.map(t=>`<div class="list-row"><span class="row-icon">${icon(t.type==='CONTEO CÍCLICO'?'clipboard-check':'arrows-move')}</span><div class="grow"><strong>${t.type}</strong><small>${t.product} · ${t.from} → ${t.to}</small></div>${badge(t.status,t.status==='Pendiente'?'warn':t.status==='En proceso'?'purple':'ok')}</div>`).join('')}</section></div>`; }

function products() {
  const data = db.products.filter((p) => `${p.name} ${p.sku} ${p.category}`.toLowerCase().includes(state.query.toLowerCase()));
  return `${pageHead('MAESTRO COMERCIAL', 'PRODUCTOS Y SKU', 'Administra identidad, precio, trazabilidad y parámetros logísticos de cada artículo.', `<button class="btn btn-primary" data-action="modal-product">${icon('plus-lg')} Nuevo producto</button>`)}<div class="toolbar"><input id="search-products" value="${state.query}" placeholder="Buscar por nombre, SKU o categoría" /> <select><option>Todos los estados</option><option>Stock crítico</option><option>Controla lote</option></select><button class="btn btn-outline" data-action="toast">${icon('download')} Exportar</button></div><div class="table-wrap"><table><thead><tr><th>SKU / producto</th><th>Categoría</th><th>Proveedor</th><th>Precio</th><th>Stock</th><th>Ubicación</th><th>Estado</th><th></th></tr></thead><tbody>${data.map(p=>`<tr><td><strong>${p.name}</strong><small>${p.sku} · Lote ${p.lot}</small></td><td>${p.category}<small>${p.brand}</small></td><td>${p.supplier}</td><td>${money(p.price)}</td><td><strong style="color:${p.stock<=p.min?'var(--red)':'var(--green)'}">${p.stock}</strong><small>Mínimo: ${p.min}</small></td><td>${badge(p.loc,'purple')}</td><td>${badge(p.stock<=p.min?'Stock crítico':p.status,p.stock<=p.min?'danger':'ok')}</td><td class="right"><button class="btn btn-outline btn-sm" data-action="edit-product" data-id="${p.id}">${icon('pencil')}</button></td></tr>`).join('') || `<tr><td colspan="8">${empty('search','Sin coincidencias','Prueba con otro nombre, SKU o categoría.')}</td></tr>`}</tbody></table></div>`;
}

function suppliers() { return `${pageHead('ABASTECIMIENTO', 'PROVEEDORES', 'Empresas que abastecen el catálogo de Don Pepe.', `<button class="btn btn-primary" data-action="modal-supplier">${icon('plus-lg')} Nuevo proveedor</button>`)}<div class="table-wrap"><table><thead><tr><th>Razón social</th><th>RUC</th><th>Contacto</th><th>Categoría</th><th>Estado</th><th></th></tr></thead><tbody>${db.suppliers.map(x=>`<tr><td><strong>${x.name}</strong></td><td>${x.ruc}</td><td>${x.contact}</td><td>${x.category}</td><td>${badge(x.status,'ok')}</td><td class="right"><button class="btn btn-outline btn-sm" data-action="toast">${icon('eye')}</button></td></tr>`).join('')}</tbody></table></div>`; }
function users() { return `${pageHead('ADMINISTRACIÓN', 'USUARIOS Y ROLES', 'Cuentas activas y acceso mínimo necesario según responsabilidad.', `<button class="btn btn-primary" data-action="modal-user">${icon('person-plus')} Nuevo usuario</button>`)}<div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Última sesión</th><th>Permisos principales</th></tr></thead><tbody>${db.users.map(u=>`<tr><td><strong>${u.name}</strong><small>${u.email}</small></td><td>${badge(u.role,u.role==='Administrador'?'purple':u.role==='Almacenero'?'warn':'ok')}</td><td>${badge(u.status,'ok')}</td><td>${u.last}</td><td><small>${u.role==='Administrador'?'Control total':'Almacenero'===u.role?'WMS, recepción, inventario':'POS y ventas propias'}</small></td></tr>`).join('')}</tbody></table></div>`; }
function catalogs() { return `${pageHead('MAESTROS', 'CATÁLOGOS', 'Categorías, marcas y reglas comerciales que normalizan el surtido.', `<button class="btn btn-primary" data-action="toast">${icon('plus-lg')} Nuevo catálogo</button>`)}<div class="grid-even"><section class="panel"><div class="panel-head"><h2>CATEGORÍAS</h2></div>${['Bebidas','Abarrotes','Lácteos','Snacks','Congelados','Higiene'].map((x,i)=>`<div class="list-row"><span class="row-icon">${icon(['cup-straw','basket','cup-hot','cookie','snow','heart'][i])}</span><div class="grow"><strong>${x}</strong><small>${[12,9,7,5,4,5][i]} SKU activos</small></div><button class="btn btn-outline btn-sm" data-action="toast">${icon('pencil')}</button></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>REGLAS DE CATÁLOGO</h2></div><p class="sub">Todo SKU debe tener identificador único, categoría, proveedor, precio, unidad de medida y estado activo.</p><div class="list-row"><span class="row-icon">${icon('upc-scan')}</span><div class="grow"><strong>SKU y EAN únicos</strong><small>Previene duplicidad comercial.</small></div>${badge('Activo','ok')}</div><div class="list-row"><span class="row-icon">${icon('calendar-event')}</span><div class="grow"><strong>Lote y FEFO</strong><small>Obligatorio para artículos con vencimiento.</small></div>${badge('Activo','ok')}</div></section></div>`; }

function purchases() { return `${pageHead('ABASTECIMIENTO', 'ÓRDENES DE COMPRA', 'Planifica compras y controla el estado de recepción de cada proveedor.', `<button class="btn btn-primary" data-action="modal-order">${icon('plus-lg')} Nueva orden</button>`)}<div class="table-wrap"><table><thead><tr><th>Orden</th><th>Proveedor</th><th>Emisión</th><th>Entrega</th><th>Líneas</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody>${db.orders.map(o=>`<tr><td><strong>${o.id}</strong></td><td>${o.supplier}</td><td>${o.date}</td><td>${o.eta}</td><td>${o.lines}</td><td>${money(o.total)}</td><td>${badge(o.status,o.status==='Pendiente'?'warn':o.status==='Parcial'?'purple':'ok')}</td><td class="right">${o.status!=='Recibida'?`<button class="btn btn-primary btn-sm" data-nav="receive">Recibir</button>`:`<button class="btn btn-outline btn-sm" data-action="toast">Ver detalle</button>`}</td></tr>`).join('')}</tbody></table></div>`; }
function receive() { const order = db.orders[0]; return `${pageHead('RECEPCIÓN GUIADA', 'RECIBIR MERCADERÍA', `Orden ${order.id} · ${order.supplier}`, `<button class="btn btn-outline" data-nav="purchases">${icon('arrow-left')} Volver</button>`)}<div class="wizard"><div class="steps"><div class="step active">1. Verificar orden</div><div class="step">2. Contar y lotear</div><div class="step">3. Asignar REC-01</div><div class="step">4. Crear tareas</div></div><section class="panel"><div class="panel-head"><div><h2>CONFIRMACIÓN DE RECEPCIÓN</h2><small>Las cantidades recibidas se almacenan temporalmente en REC-01.</small></div>${badge('PENDIENTE','warn')}</div>${db.products.slice(0,3).map((p,i)=>`<div class="list-row"><span class="row-icon">${icon('box-seam')}</span><div class="grow"><strong>${p.name}</strong><small>${p.sku} · lote sugerido ${i===0?'IK-2409':p.lot}</small></div><div><label class="label" style="margin:0 0 3px">Recibido</label><input style="width:90px;padding:7px" type="number" value="${[48,24,36][i]}" /></div></div>`).join('')}<div class="route-cards" style="margin-top:22px"><div class="route-card"><small class="eyebrow">ORIGEN</small><strong>MUELLE</strong><span>Proveedor y documento verificados</span></div><div class="route-arrow">${icon('arrow-right')}</div><div class="route-card"><small class="eyebrow">DESTINO TEMPORAL</small><strong>REC-01</strong><span>38/72 unidades de capacidad ocupada</span></div></div><div class="modal-actions"><button class="btn btn-outline" data-action="toast">Guardar borrador</button><button class="btn btn-primary" data-action="confirm-receive">${icon('check2-circle')} Confirmar recepción</button></div></section></div>`; }

function locations() { return `${pageHead('TOPOLOGÍA WMS', 'ZONAS Y UBICACIONES LOC', 'Visualiza la capacidad y disponibilidad física antes de mover inventario.', `<button class="btn btn-primary" data-action="modal-location">${icon('plus-lg')} Nueva ubicación</button>`)}<div class="grid-even"><section class="panel"><div class="panel-head"><div><h2>MAPA DE ZONAS</h2><small>Configuración típica de un minimarket WMS</small></div></div><div class="zone-map"><div class="zone rec"><strong>REC</strong><small>Recepción temporal</small>${badge('1 LOC','warn')}</div><div class="zone res"><strong>RSV</strong><small>Reserva seca</small>${badge('168 / 240','purple')}</div><div class="zone pick"><strong>PCK</strong><small>Picking seco</small>${badge('94 / 120','warn')}</div><div class="zone cold"><strong>FRI</strong><small>Refrigerados</small>${badge('106 / 150','ok')}</div><div class="zone cold"><strong>CON</strong><small>Congelados</small>${badge('74 / 120','ok')}</div><div class="zone qua"><strong>QUA</strong><small>Cuarentena</small>${badge('4 / 30','danger')}</div></div></section><section class="panel"><div class="panel-head"><div><h2>REGLAS DE MOVIMIENTO</h2><small>Validaciones previas al traslado</small></div></div><div class="list-row"><span class="row-icon">${icon('thermometer-half')}</span><div class="grow"><strong>Compatibilidad de temperatura</strong><small>Frío y congelado solo se mueven entre LOC compatibles.</small></div></div><div class="list-row"><span class="row-icon">${icon('speedometer')}</span><div class="grow"><strong>Capacidad máxima</strong><small>El sistema bloquea destinos sin espacio disponible.</small></div></div><div class="list-row"><span class="row-icon">${icon('shield-check')}</span><div class="grow"><strong>Picking autorizado</strong><small>El POS despacha solamente desde ubicaciones PCK.</small></div></div></section></div><div class="location-grid" style="margin-top:16px">${db.locations.map(l=>`<article class="location" style="--zone:var(--${l.color})"><div class="location-code">${l.code}</div><small>${l.zone} · ${l.temp}</small><div class="split"><span>Ocupación</span><strong>${l.used}/${l.capacity}</strong></div><div class="progress"><b style="width:${l.used/l.capacity*100}%"></b></div><div class="task-footer" style="margin-top:14px">${badge(l.status,l.status==='Disponible'?'ok':'danger')}<button class="btn btn-outline btn-sm" data-action="toast">Ver stock</button></div></article>`).join('')}</div>`; }

function tasks() { const tasks = db.tasks; return `${pageHead('EJECUCIÓN DIRIGIDA', 'TAREAS WMS', 'Sigue origen, lote, cantidad y destino para reducir errores operativos.', `<button class="btn btn-primary" data-action="modal-task">${icon('plus-lg')} Nueva tarea</button>`)}<div class="metrics">${metric(tasks.filter(t=>t.status==='Pendiente').length,'Pendientes','inboxes','var(--yellow)')}${metric(tasks.filter(t=>t.status==='En proceso').length,'En proceso','arrow-repeat','var(--blue)')}${metric(tasks.filter(t=>t.status==='Completada').length,'Completadas','check-circle','var(--green)')}${metric(tasks.filter(t=>t.priority==='Alta'&&t.status!=='Completada').length,'Prioridad alta','exclamation-triangle','var(--red)')}</div><div class="task-grid">${tasks.map(t=>`<article class="task" style="--accent:${t.priority==='Alta'?'var(--red)':t.priority==='Media'?'var(--yellow)':'var(--blue)'}"><div class="task-top">${badge(t.type,'purple')}${badge(t.priority,t.priority==='Alta'?'danger':t.priority==='Media'?'warn':'')}</div><h3>${t.product}</h3><p>${t.sku} · Lote ${t.lot} · ${t.qty} unidades</p><div class="route"><span>${t.from}</span>${icon('arrow-right')}<span>${t.to}</span></div><div class="task-footer"><span>${badge(t.status,t.status==='Pendiente'?'warn':t.status==='En proceso'?'purple':'ok')}</span>${t.status==='Pendiente'?`<button class="btn btn-primary btn-sm" data-action="take-task" data-id="${t.id}">Tomar tarea</button>`:t.status==='En proceso'?`<button class="btn btn-primary btn-sm" data-action="open-task" data-id="${t.id}">Continuar</button>`:badge('Confirmada','ok')}</div></article>`).join('')}</div>`; }
function taskFlow() { const t = db.tasks.find(x=>x.id===state.selectedTask) || db.tasks[0]; return `${pageHead('EJECUCIÓN WMS', t.type, `Tarea ${t.id} · Confirma cada punto antes de actualizar el inventario.`, `<button class="btn btn-outline" data-nav="tasks">${icon('arrow-left')} Volver</button>`)}<div class="wizard"><div class="steps"><div class="step active">1. Origen</div><div class="step active">2. SKU y lote</div><div class="step">3. Destino</div><div class="step">4. Confirmar</div></div><section class="panel"><div class="panel-head"><div><h2>VERIFICA EL MOVIMIENTO</h2><small>La operación se registra en kardex al completar la tarea.</small></div>${badge(t.priority,t.priority==='Alta'?'danger':'warn')}</div><div class="route-cards"><div class="route-card"><small class="eyebrow">RETIRAR DE</small><strong>${t.from}</strong><span>${t.product}<br/>Lote ${t.lot} · ${t.qty} und.</span></div><div class="route-arrow">${icon('arrow-right')}</div><div class="route-card"><small class="eyebrow">LLEVAR A</small><strong>${t.to}</strong><span>Destino compatible y con capacidad disponible.</span></div></div><div class="form-grid" style="margin-top:22px"><label><span class="label">SKU escaneado</span><input value="${t.sku}" /></label><label><span class="label">Cantidad física</span><input type="number" value="${t.qty}" /></label><label class="full"><span class="label">Confirmación del operario</span><select><option>SKU, lote y destino verificados</option><option>Reportar incidencia</option></select></label></div><div class="modal-actions"><button class="btn btn-outline" data-nav="tasks">Reportar diferencia</button><button class="btn btn-primary" data-action="complete-task" data-id="${t.id}">${icon('check2-circle')} Confirmar movimiento</button></div></section></div>`; }

function inventory() { return `${pageHead('EXISTENCIAS', 'INVENTARIO POR UBICACIÓN', 'Consulta saldo disponible por SKU, lote y posición física.', `<button class="btn btn-outline" data-nav="kardex">${icon('arrow-left-right')} Ver kardex</button>`)}<div class="toolbar"><input placeholder="Buscar SKU, lote o LOC" /><select><option>Todas las zonas</option><option>Picking</option><option>Reserva</option></select></div><div class="table-wrap"><table><thead><tr><th>LOC</th><th>SKU / producto</th><th>Lote</th><th>Vencimiento</th><th>Disponible</th><th>Estado</th><th></th></tr></thead><tbody>${db.products.map(p=>`<tr><td>${badge(p.loc,'purple')}</td><td><strong>${p.name}</strong><small>${p.sku}</small></td><td>${p.lot}</td><td>${p.expires}</td><td>${p.stock}</td><td>${badge(p.stock<=p.min?'Bajo':'Disponible',p.stock<=p.min?'danger':'ok')}</td><td class="right">${p.stock<=p.min?`<button class="btn btn-primary btn-sm" data-action="quick-task" data-id="${p.id}">Reabastecer</button>`:''}</td></tr>`).join('')}</tbody></table></div>`; }
function health() { const critical = db.products.filter(p=>p.stock<=p.min); return `${pageHead('PREVENCIÓN OPERATIVA', 'SALUD DE STOCK', 'Semáforo de disponibilidad, vencimiento, rotación y diferencias pendientes.', `<button class="btn btn-primary" data-nav="tasks">${icon('arrows-move')} Crear tarea</button>`)}<div class="metrics">${metric(critical.length,'Stock crítico','exclamation-triangle','var(--red)')}${metric(3,'Próximos a vencer','calendar-event','var(--orange)')}${metric(db.audits.filter(a=>a.status==='Pendiente').length,'Diferencias','clipboard-x','var(--yellow)')}${metric(12,'SKU saludables','heart-pulse','var(--green)')}</div><div class="grid-even"><section class="panel"><div class="panel-head"><div><h2>ACCIONES RECOMENDADAS</h2><small>Priorizadas por impacto operativo</small></div></div>${critical.map(p=>`<div class="list-row"><span class="row-icon" style="color:var(--red)">${icon('exclamation-triangle')}</span><div class="grow"><strong>Reabastecer ${p.name}</strong><small>${p.stock}/${p.min} en ${p.loc}; hay reserva disponible.</small></div><button class="btn btn-primary btn-sm" data-action="quick-task" data-id="${p.id}">Crear</button></div>`).join('')}<div class="list-row"><span class="row-icon" style="color:var(--orange)">${icon('calendar-event')}</span><div class="grow"><strong>Revisar lote PC-2408</strong><small>Vence en menos de 90 días; aplicar FEFO.</small></div><button class="btn btn-outline btn-sm" data-nav="lots">Ver lote</button></div></section><section class="panel"><div class="panel-head"><div><h2>QUÉ MONITOREA ESTE MÓDULO</h2><small>Información útil, no solo un mensaje de estado.</small></div></div><div class="list-row"><span class="row-icon">${icon('activity')}</span><div class="grow"><strong>Nivel de stock</strong><small>Compara disponible con mínimo y objetivo de picking.</small></div></div><div class="list-row"><span class="row-icon">${icon('calendar-range')}</span><div class="grow"><strong>Vencimiento y FEFO</strong><small>Detecta lotes cercanos a vencer o bloqueados.</small></div></div><div class="list-row"><span class="row-icon">${icon('clipboard-data')}</span><div class="grow"><strong>Conciliación física</strong><small>Expone conteos pendientes de aprobación.</small></div></div></section></div>`; }

function lots() { return `${pageHead('TRAZABILIDAD', 'LOTES Y VENCIMIENTOS', 'Controla fecha, ubicación y disponibilidad con despacho FEFO.', `<button class="btn btn-outline" data-action="toast">${icon('download')} Exportar</button>`)}<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Lote</th><th>LOC</th><th>Vencimiento</th><th>Días</th><th>Saldo</th><th>Estado</th></tr></thead><tbody>${db.products.map((p,i)=>`<tr><td><strong>${p.name}</strong><small>${p.sku}</small></td><td>${p.lot}</td><td>${badge(p.loc,'purple')}</td><td>${p.expires}</td><td>${[168,97,218,42,224,351,86,151][i]}</td><td>${p.stock}</td><td>${badge(i===3?'Próximo a vencer':'Vigente',i===3?'warn':'ok')}</td></tr>`).join('')}</tbody></table></div>`; }
function kardex() { const rows = [['03/09/2026 12:44','Venta','V-00192','Inca Kola 1.5 L','IK-2408','PCK-SECO-01','',2,22,'Ana Torres'],['03/09/2026 11:30','Reabastecimiento','TSK-032','Pilsen Callao 620 ml','PC-2408','PCK-SECO-01',24,'',8,'Carlos Ramos'],['03/09/2026 09:15','Recepción','OC-2026-0048','Inca Kola 1.5 L','IK-2409','REC-01',48,'',48,'Carlos Ramos'],['02/09/2026 16:10','Ajuste aprobado','AUD-017','Yogurt Laive 1 L','YL-2407','PCK-FRIO-01','',0,15,'Frank Admin']]; return `${pageHead('TRAZABILIDAD', 'KARDEX DE INVENTARIO', 'Historial inalterable de entradas, salidas, ajustes y responsables.', `<button class="btn btn-outline" data-action="toast">${icon('download')} Exportar</button>`)}<div class="toolbar"><input placeholder="SKU, lote, documento o LOC" /><select><option>Todos los movimientos</option><option>Entrada</option><option>Salida</option><option>Ajuste</option></select></div><div class="table-wrap"><table><thead><tr><th>Fecha Perú</th><th>Tipo</th><th>Referencia</th><th>Producto / lote</th><th>LOC</th><th>Entrada</th><th>Salida</th><th>Saldo</th><th>Usuario</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${badge(r[1],r[1]==='Venta'?'danger':r[1]==='Recepción'?'ok':'purple')}</td><td>${r[2]}</td><td><strong>${r[3]}</strong><small>${r[4]}</small></td><td>${r[5]}</td><td style="color:var(--green)">${r[6]}</td><td style="color:var(--red)">${r[7]}</td><td>${r[8]}</td><td>${r[9]}</td></tr>`).join('')}</tbody></table></div>`; }
function audits() { return `${pageHead('CONTROL FÍSICO', 'CONTEOS Y AUDITORÍAS', 'Toda diferencia requiere evidencia y aprobación de otro responsable.', `<button class="btn btn-primary" data-action="modal-audit">${icon('plus-lg')} Nuevo conteo</button>`)}<div class="table-wrap"><table><thead><tr><th>Auditoría</th><th>Ubicación</th><th>Producto</th><th>Esperado</th><th>Físico</th><th>Diferencia</th><th>Estado</th><th></th></tr></thead><tbody>${db.audits.map(a=>`<tr><td><strong>${a.id}</strong><small>${a.date} · ${a.owner}</small></td><td>${badge(a.loc,'purple')}</td><td>${a.product}</td><td>${a.expected}</td><td>${a.counted}</td><td style="color:${a.diff?'var(--red)':'var(--green)'}">${a.diff>0?'+':''}${a.diff}</td><td>${badge(a.status,a.status==='Pendiente'?'warn':'ok')}</td><td class="right">${a.status==='Pendiente'&&state.role==='administrador'?`<button class="btn btn-primary btn-sm" data-action="approve-audit" data-id="${a.id}">Aprobar</button>`:a.status==='Pendiente'?badge('En revisión','warn'):badge('Validada','ok')}</td></tr>`).join('')}</tbody></table></div><div class="panel" style="margin-top:16px"><strong>${icon('shield-check')} Regla de segregación</strong><p class="sub">El almacenero registra el conteo; el administrador aprueba o rechaza la diferencia. El autor no puede aprobar su propio conteo.</p></div>`; }

function pos() { const total = state.cart.reduce((sum,item)=>sum+item.price*item.qty,0); return `${pageHead('VENTA RÁPIDA', 'PUNTO DE VENTA', 'Busca, agrega y cobra sin salir de la operación.', `<button class="btn btn-outline" data-nav="sales">${icon('receipt')} Mis ventas</button>`)}<div class="pos"><section class="panel"><div class="toolbar"><input id="pos-search" placeholder="Buscar por nombre, SKU o EAN" /><button class="btn btn-outline" data-action="toast">${icon('upc-scan')} Escanear</button></div><div class="product-grid">${db.products.map(p=>`<button class="product-tile" data-action="add-cart" data-id="${p.id}">${icon('box-seam')}<span>${p.name}</span><small>${p.sku} · ${p.stock} disponibles</small><strong>${money(p.price)}</strong></button>`).join('')}</div></section><aside class="panel"><div class="panel-head"><div><h2>CARRITO ACTUAL</h2><small>${state.cart.reduce((a,x)=>a+x.qty,0)} artículos</small></div><button class="btn btn-outline btn-sm" data-action="clear-cart">Limpiar</button></div>${state.cart.length?state.cart.map(item=>`<div class="cart-row"><div><strong>${item.name}</strong><small>${money(item.price)} c/u</small></div><div class="qty"><button data-action="cart-minus" data-id="${item.id}">−</button><b>${item.qty}</b><button data-action="cart-plus" data-id="${item.id}">+</button></div><strong>${money(item.price*item.qty)}</strong></div>`).join('') : empty('cart-x','Carrito vacío','Selecciona productos para iniciar una venta.')}<div class="cart-total"><span>Total a cobrar</span><strong>${money(total)}</strong></div><label class="label">Método de pago</label><select><option>Yape / Plin</option><option>Efectivo</option><option>Tarjeta</option></select><button class="btn btn-primary btn-wide" data-action="checkout" ${!state.cart.length?'disabled':''}>${icon('cash-coin')} Cobrar venta</button></aside></div>`; }
function sales() { const list = state.role==='vendedor'?db.sales.filter(s=>s.seller==='Ana Torres'):db.sales; return `${pageHead('HISTORIAL COMERCIAL', state.role==='vendedor'?'MIS VENTAS':'VENTAS', state.role==='vendedor'?'Consulta únicamente tus comprobantes registrados.':'Consulta comprobantes y actividad de todos los vendedores.', `<button class="btn btn-primary" data-nav="pos">${icon('cart3')} Nueva venta</button>`)}<div class="table-wrap"><table><thead><tr><th>Comprobante</th><th>Fecha Perú</th><th>Vendedor</th><th>Líneas</th><th>Método</th><th>Total</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><strong>${s.id}</strong></td><td>${s.date}</td><td>${s.seller}</td><td>${s.lines}</td><td>${badge(s.method,'purple')}</td><td><strong style="color:var(--yellow)">${money(s.total)}</strong></td><td class="right"><button class="btn btn-outline btn-sm" data-action="toast">${icon('eye')}</button></td></tr>`).join('')}</tbody></table></div>`; }
function reports() { return `${pageHead('INTELIGENCIA DE NEGOCIO', 'REPORTES', 'Indicadores consolidados para decisiones de compra, ventas e inventario.', `<button class="btn btn-primary" data-action="toast">${icon('file-earmark-arrow-down')} Exportar</button>`)}<div class="toolbar"><select><option>Últimos 30 días</option><option>Semana actual</option><option>Mes actual</option></select><select><option>Todas las categorías</option><option>Bebidas</option><option>Abarrotes</option></select></div><div class="metrics">${metric(money(18420.6),'Ventas del período','graph-up-arrow','var(--green)')}${metric('18.4%','Margen estimado','cash-coin','var(--yellow)')}${metric('4.2 días','Rotación promedio','arrow-repeat','var(--blue)')}${metric('96%','Tareas a tiempo','check2-circle','var(--purple-2)')}</div><div class="grid-even"><section class="panel"><div class="panel-head"><div><h2>VENTAS POR CATEGORÍA</h2><small>Participación del período</small></div></div>${['Bebidas','Abarrotes','Lácteos','Snacks','Higiene'].map((x,i)=>`<div class="list-row"><div class="grow"><strong>${x}</strong><div class="progress"><b style="width:${[88,71,54,42,31][i]}%"></b></div></div><strong>${money([6210,4280,3150,2740,2040][i])}</strong></div>`).join('')}</section><section class="panel"><div class="panel-head"><div><h2>INDICADORES WMS</h2><small>Productividad operacional</small></div></div>${[['Tareas completadas', '86 / 92', 'ok'],['Recepciones sin diferencia', '92%', 'ok'],['Conteos pendientes', '1', 'warn'],['Lotes críticos', '1', 'danger']].map(x=>`<div class="list-row"><span class="row-icon">${icon('bar-chart')}</span><div class="grow"><strong>${x[0]}</strong><small>Periodo seleccionado</small></div>${badge(x[1],x[2])}</div>`).join('')}</section></div>`; }
function settings() { return `${pageHead('PARÁMETROS', 'CONFIGURACIÓN', 'Variables del negocio y políticas que afectan la operación.', `<button class="btn btn-primary" data-action="toast">${icon('check2')} Guardar cambios</button>`)}<div class="grid-even"><section class="panel"><div class="panel-head"><h2>NEGOCIO</h2></div><label class="label">Nombre comercial</label><input value="Minimarket Don Pepe" /><label class="label">IGV</label><input value="18%" /><label class="label">Zona horaria</label><select><option>America/Lima · PET UTC−5</option></select></section><section class="panel"><div class="panel-head"><h2>ALERTAS OPERATIVAS</h2></div>${[['Stock bajo mínimo','Notificar al almacenero'],['Lote próximo a vencer','Notificar al administrador'],['Diferencia de conteo','Requiere aprobación'],['Capacidad de LOC','Bloquear movimiento incompatible']].map(x=>`<div class="list-row"><div class="grow"><strong>${x[0]}</strong><small>${x[1]}</small></div><span class="badge ok">${icon('toggle-on')} Activa</span></div>`).join('')}</section></div>`; }

const pages = { dashboard, warehouse, products, suppliers, users, catalogs, purchases, receive, locations, tasks, taskFlow, inventory, health, lots, kardex, audits, pos, sales, reports, settings };
function renderLogin() { return `<div class="login"><section class="login-hero"><div class="login-brand brand"><span class="brand-mark">${icon('shop')}</span><span><strong>DON PEPE</strong><small>SISTEMA DE MINIMARKET</small></span></div><div class="hero-copy"><span class="eyebrow">OPERACIÓN CONECTADA</span><h1>CONTROL TOTAL DEL MINIMARKET.</h1><p>Gestiona ventas, inventario, recepción, ubicaciones, lotes y tareas WMS con trazabilidad en tiempo real.</p><div class="hero-stats"><div class="hero-stat"><strong>42</strong><small>SKU ACTIVOS</small></div><div class="hero-stat"><strong>7</strong><small>ALERTAS HOY</small></div><div class="hero-stat"><strong>+143</strong><small>MOVIMIENTOS</small></div></div></div></section><section class="login-panel"><div class="login-box"><span class="eyebrow">DON PEPE · ACCESO SEGURO</span><h1>INICIAR SESIÓN</h1><p class="sub">Elige un perfil para recorrer el prototipo funcional.</p><label class="label">Correo electrónico</label><input value="frank@minimarket.com" /><label class="label">Contraseña</label><input type="password" value="admin123" /><label class="label">Rol de acceso</label><div class="role-grid"><button class="role-choice selected" data-role="administrador">${icon('shield-lock')}Administrador</button><button class="role-choice" data-role="almacenero">${icon('boxes')}Almacenero</button><button class="role-choice" data-role="vendedor">${icon('cart3')}Vendedor</button></div><button class="btn btn-primary btn-wide" data-action="login">Ingresar al sistema ${icon('arrow-right')}</button><p class="demo-note">Prototipo estático · datos simulados · Perú (PET)</p></div></section></div>`; }
function renderModal() { if (!state.modal) return ''; const forms = {
  product: ['Nuevo producto','Completa los datos comerciales y logísticos del SKU.',`<label><span class="label">Nombre</span><input name="name" placeholder="Ej. Agua San Luis 625 ml" required /></label><label><span class="label">SKU</span><input name="sku" placeholder="DP-BEB-009" required /></label><label><span class="label">Categoría</span><select name="category"><option>Bebidas</option><option>Abarrotes</option><option>Lácteos</option><option>Snacks</option></select></label><label><span class="label">Precio de venta</span><input name="price" type="number" value="3.50" /></label><label><span class="label">Stock mínimo</span><input name="min" type="number" value="12" /></label><label><span class="label">Proveedor</span><select name="supplier">${db.suppliers.map(s=>`<option>${s.name}</option>`).join('')}</select></label>`],
  supplier: ['Nuevo proveedor','Registra la empresa responsable del abastecimiento.',`<label><span class="label">Razón social</span><input name="name" required /></label><label><span class="label">RUC</span><input name="ruc" required /></label><label><span class="label">Contacto</span><input name="contact" /></label><label><span class="label">Categoría</span><select name="category"><option>Bebidas</option><option>Abarrotes</option><option>Lácteos</option></select></label>`],
  user: ['Nuevo usuario','La asignación de rol define el menú y las acciones disponibles.',`<label><span class="label">Nombre completo</span><input name="name" required /></label><label><span class="label">Correo</span><input name="email" type="email" required /></label><label class="full"><span class="label">Rol</span><select name="role"><option>Administrador</option><option>Almacenero</option><option>Vendedor</option></select></label>`],
  order: ['Nueva orden de compra','Simulación de la creación de una orden para proveedor.',`<label class="full"><span class="label">Proveedor</span><select name="supplier">${db.suppliers.map(s=>`<option>${s.name}</option>`).join('')}</select></label><label><span class="label">Fecha esperada</span><input type="date" /></label><label><span class="label">Líneas</span><input type="number" value="3" /></label>`],
  location: ['Nueva ubicación LOC','Configura capacidad, condición y permiso de picking.',`<label><span class="label">Código LOC</span><input name="code" placeholder="RSV-SECO-02" /></label><label><span class="label">Zona</span><select name="zone"><option>Reserva seca</option><option>Picking seco</option><option>Refrigerados</option><option>Cuarentena</option></select></label><label><span class="label">Capacidad</span><input name="capacity" type="number" value="60" /></label><label><span class="label">Temperatura</span><select name="temp"><option>Ambiente</option><option>2–6 °C</option><option>−18 °C</option></select></label>`],
  task: ['Nueva tarea WMS','Elige un tipo y el sistema propone el movimiento correcto.',`<label><span class="label">Tipo</span><select name="type"><option>REABASTECIMIENTO</option><option>PUT-AWAY</option><option>TRASLADO</option><option>CONTEO CÍCLICO</option></select></label><label><span class="label">Producto</span><select name="product">${db.products.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label><span class="label">Origen</span><select name="from">${db.locations.map(l=>`<option>${l.code}</option>`).join('')}</select></label><label><span class="label">Destino</span><select name="to">${db.locations.map(l=>`<option>${l.code}</option>`).join('')}</select></label><label class="full"><span class="label">Cantidad</span><input name="qty" type="number" value="12" /></label>`],
  audit: ['Nuevo conteo físico','Registra el saldo observado; no podrás aprobar tu propio conteo.',`<label><span class="label">Ubicación LOC</span><select name="loc">${db.locations.map(l=>`<option>${l.code}</option>`).join('')}</select></label><label><span class="label">Producto</span><select name="product">${db.products.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label><span class="label">Cantidad física</span><input name="counted" type="number" value="0" /></label><label><span class="label">Motivo</span><select><option>Conteo cíclico</option><option>Incidencia operativa</option></select></label>`],
  editproduct: ['Editar producto','Actualiza información comercial del SKU.',`<label><span class="label">Nombre</span><input name="name" value="${db.products.find(p=>p.id===state.editId).name}" /></label><label><span class="label">Precio</span><input name="price" type="number" value="${db.products.find(p=>p.id===state.editId).price}" /></label><label class="full"><span class="label">Stock mínimo</span><input name="min" type="number" value="${db.products.find(p=>p.id===state.editId).min}" /></label>`]
  }; const [title,desc,fields] = forms[state.modal]; return `<div class="modal-backdrop"><form class="modal" id="static-form"><div class="panel-head"><div><h2>${title}</h2><p>${desc}</p></div><button type="button" class="btn btn-outline btn-sm" data-action="close-modal">${icon('x-lg')}</button></div><div class="form-grid">${fields}</div><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${icon('check2')} Guardar</button></div></form></div>`; }
function renderToast() { return state.toast ? `<div class="toast">${icon('check2-circle')}<span>${state.toast}</span></div>` : ''; }
function render() { const app=document.querySelector('#app'); app.innerHTML=state.role?`<div class="shell">${sidebar()}<main class="main">${topbar()}<div class="content">${(pages[state.page]||dashboard)()}</div></main></div>${renderModal()}${renderToast()}`:renderLogin(); bind(); }

function showToast(message) { state.toast=message; render(); setTimeout(()=>{state.toast=null;render();},2600); }
function addCart(id){ const p=db.products.find(x=>x.id===id); const item=state.cart.find(x=>x.id===id); if(item)item.qty+=1; else state.cart.push({...p,qty:1}); render(); }
function submitForm(form) { const val=(name)=>form.elements[name]?.value; if(state.modal==='product'){const id=Math.max(...db.products.map(x=>x.id))+1;db.products.unshift({id,sku:val('sku'),name:val('name'),category:val('category'),brand:'Nueva marca',supplier:val('supplier'),price:+val('price'),stock:0,min:+val('min'),lot:'PENDIENTE',expires:'—',loc:'REC-01',status:'Activo'});state.modal=null;showToast('Producto creado. Ahora puedes recibirlo en REC-01.');}
  else if(state.modal==='editproduct'){const p=db.products.find(x=>x.id===state.editId);p.name=val('name');p.price=+val('price');p.min=+val('min');state.modal=null;showToast('Producto actualizado correctamente.');}
  else if(state.modal==='supplier'){db.suppliers.push({name:val('name'),ruc:val('ruc'),contact:val('contact'),category:val('category'),status:'Activo'});state.modal=null;showToast('Proveedor registrado.');}
  else if(state.modal==='user'){db.users.push({name:val('name'),email:val('email'),role:val('role'),status:'Activo',last:'Sin acceso'});state.modal=null;showToast('Usuario creado y rol asignado.');}
  else if(state.modal==='order'){db.orders.unshift({id:`OC-2026-00${49+db.orders.length}`,supplier:val('supplier'),date:'03/09/2026',lines:3,total:420,status:'Pendiente',eta:'Por coordinar'});state.modal=null;showToast('Orden de compra creada.');}
  else if(state.modal==='location'){db.locations.push({code:val('code'),zone:val('zone'),type:'RSV',capacity:+val('capacity'),used:0,temp:val('temp'),color:'purple',status:'Disponible'});state.modal=null;showToast('Ubicación LOC registrada.');}
  else if(state.modal==='task'){const p=db.products.find(x=>x.id===+val('product'));db.tasks.unshift({id:`TSK-0${35+db.tasks.length}`,type:val('type'),product:p.name,sku:p.sku,qty:+val('qty'),lot:p.lot,from:val('from'),to:val('to'),priority:'Media',status:'Pendiente',owner:'Sin asignar'});state.modal=null;showToast('Tarea creada y enviada a la bandeja WMS.');}
  else if(state.modal==='audit'){const p=db.products.find(x=>x.id===+val('product'));const counted=+val('counted');db.audits.unshift({id:`AUD-0${19+db.audits.length}`,loc:val('loc'),product:p.name,expected:p.stock,counted,diff:counted-p.stock,status:'Pendiente',owner:roleMeta[state.role].name,date:`03/09/2026 ${clock().slice(-5)}`});state.modal=null;showToast('Conteo enviado para aprobación.');}
}
function bind() { document.querySelectorAll('[data-nav]').forEach(el=>el.addEventListener('click',()=>{state.page=el.dataset.nav;state.modal=null;render();})); document.querySelectorAll('[data-role]').forEach(el=>el.addEventListener('click',()=>{document.querySelectorAll('[data-role]').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');state.pendingRole=el.dataset.role;})); document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>{const a=el.dataset.action,id=el.dataset.id;if(a==='login'){state.role=state.pendingRole||'administrador';state.page=state.role==='administrador'?'dashboard':state.role==='almacenero'?'warehouse':'pos';render();}if(a==='logout'){state.role=null;state.page='login';state.cart=[];render();}if(a==='toggle-sidebar')document.querySelector('#sidebar').classList.toggle('open');if(a==='toast')showToast('Acción simulada correctamente en el prototipo.');if(a==='modal-product'){state.modal='product';render();}if(a==='modal-supplier'){state.modal='supplier';render();}if(a==='modal-user'){state.modal='user';render();}if(a==='modal-order'){state.modal='order';render();}if(a==='modal-location'){state.modal='location';render();}if(a==='modal-task'){state.modal='task';render();}if(a==='modal-audit'){state.modal='audit';render();}if(a==='edit-product'){state.modal='editproduct';state.editId=+id;render();}if(a==='close-modal'){state.modal=null;render();}if(a==='add-cart')addCart(+id);if(a==='cart-plus'){const item=state.cart.find(x=>x.id===+id);item.qty+=1;render();}if(a==='cart-minus'){const item=state.cart.find(x=>x.id===+id);item.qty-=1;if(!item.qty)state.cart=state.cart.filter(x=>x.id!==+id);render();}if(a==='clear-cart'){state.cart=[];render();}if(a==='checkout'){const total=state.cart.reduce((s,x)=>s+x.price*x.qty,0);db.sales.unshift({id:`V-00${193+db.sales.length}`,seller:roleMeta[state.role].name,date:`03/09/2026 ${clock().slice(-5)}`,lines:state.cart.length,total,method:'Yape'});state.cart=[];showToast(`Venta cobrada por ${money(total)}. Comprobante generado.`);}if(a==='confirm-receive'){db.orders[0].status='Recibida';db.tasks.unshift({id:'TSK-035',type:'PUT-AWAY',product:'Inca Kola 1.5 L',sku:'DP-BEB-001',qty:48,lot:'IK-2409',from:'REC-01',to:'RSV-SECO-01',priority:'Alta',status:'Pendiente',owner:'Sin asignar'});state.page='tasks';showToast('Recepción confirmada. Se creó una tarea PUT-AWAY.');}if(a==='take-task'){const t=db.tasks.find(x=>x.id===id);t.status='En proceso';t.owner=roleMeta[state.role].name;state.selectedTask=id;state.page='taskFlow';render();}if(a==='open-task'){state.selectedTask=id;state.page='taskFlow';render();}if(a==='complete-task'){const t=db.tasks.find(x=>x.id===id);t.status='Completada';state.page='tasks';showToast('Movimiento confirmado y registrado en kardex.');}if(a==='quick-task'){const p=db.products.find(x=>x.id===+id);db.tasks.unshift({id:`TSK-0${35+db.tasks.length}`,type:'REABASTECIMIENTO',product:p.name,sku:p.sku,qty:p.min*2,lot:p.lot,from:'RSV-SECO-01',to:p.loc,priority:'Alta',status:'Pendiente',owner:'Sin asignar'});state.page='tasks';showToast('Tarea de reabastecimiento creada.');}if(a==='approve-audit'){const item=db.audits.find(x=>x.id===id);item.status='Aprobada';showToast('Diferencia aprobada. Se generó el ajuste con trazabilidad.');}})); document.querySelector('#search-products')?.addEventListener('input',(e)=>{state.query=e.target.value;render();}); document.querySelector('#static-form')?.addEventListener('submit',(e)=>{e.preventDefault();submitForm(e.currentTarget);}); }
render();
